INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-CI001', 'HDSAT-RW-M24-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Universal basic income (UBI) is a social welfare proposal in which all members of a given population regularly receive a minimum income in the form of an unconditional transfer payment, i.e., without a means test or need to perform work. In contrast, a guaranteed minimum income (GMI) is paid only to those who do not already receive an income that is enough to live on. A UBI would be received independently of any other income. If the level is sufficient to meet a person''s basic needs (i.e., at or above the poverty line), it is considered a full basic income; if it is less than that amount, it is called a partial basic income. As of 2026, no country has implemented a full UBI system, but two countries—Mongolia and Iran—have or had a partial UBI, Mongolia from 2010 to 2012, and Iran still to this day. There have been numerous pilot projects, and the idea is discussed in many countries. Some have labelled UBI as utopian due to its historical origin. There are several welfare arrangements that can be considered similar to basic income, although they are not unconditional. Many countries have a system of child benefit, which is essentially a basic income for guardians of children. A pension may be a basic income for retired persons.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Every country has implemented a full universal basic income."}, {"id": "B", "text": "Universal basic income is an unconditional payment to everyone, distinct from means-tested aid, and no country has fully adopted it."}, {"id": "C", "text": "Universal basic income is paid only to people who cannot work."}, {"id": "D", "text": "Universal basic income requires recipients to perform work."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Universal basic income", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Universal_basic_income', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-CI001', 'B', ARRAY['B']::TEXT[], 'The passage defines UBI, contrasts it with related programs, and describes its limited implementation.', '{"C": "The text defines UBI as unconditional, without a means test or work requirement.", "A": "The text says no country has implemented a full UBI system.", "D": "The text says it is paid without the need to perform work."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-INF001', 'HDSAT-RW-M24-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Universal basic income (UBI) is a social welfare proposal in which all members of a given population regularly receive a minimum income in the form of an unconditional transfer payment, i.e., without a means test or need to perform work. In contrast, a guaranteed minimum income (GMI) is paid only to those who do not already receive an income that is enough to live on. A UBI would be received independently of any other income. If the level is sufficient to meet a person''s basic needs (i.e., at or above the poverty line), it is considered a full basic income; if it is less than that amount, it is called a partial basic income. As of 2026, no country has implemented a full UBI system, but two countries—Mongolia and Iran—have or had a partial UBI, Mongolia from 2010 to 2012, and Iran still to this day. There have been numerous pilot projects, and the idea is discussed in many countries. Some have labelled UBI as utopian due to its historical origin. There are several welfare arrangements that can be considered similar to basic income, although they are not unconditional. Many countries have a system of child benefit, which is essentially a basic income for guardians of children. A pension may be a basic income for retired persons.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-INF001', 'A', ARRAY['A']::TEXT[], 'Universal, unconditional payments go to everyone regardless of earnings.', '{"C": "The text says UBI is unconditional and independent of other income.", "D": "A means test would exclude high earners, but UBI has none.", "B": "The text describes a minimum income, not a payment scaled upward by salary."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-TS001', 'HDSAT-RW-M24-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Universal basic income (UBI) is a social welfare proposal in which all members of a given population regularly receive a minimum income in the form of an unconditional transfer payment, i.e., without a means test or need to perform work. In contrast, a guaranteed minimum income (GMI) is paid only to those who do not already receive an income that is enough to live on. A UBI would be received independently of any other income. If the level is sufficient to meet a person''s basic needs (i.e., at or above the poverty line), it is considered a full basic income; if it is less than that amount, it is called a partial basic income. As of 2026, no country has implemented a full UBI system, but two countries—Mongolia and Iran—have or had a partial UBI, Mongolia from 2010 to 2012, and Iran still to this day. There have been numerous pilot projects, and the idea is discussed in many countries. Some have labelled UBI as utopian due to its historical origin. There are several welfare arrangements that can be considered similar to basic income, although they are not unconditional. Many countries have a system of child benefit, which is essentially a basic income for guardians of children. A pension may be a basic income for retired persons.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares UBI with universal healthcare in detail."}, {"id": "B", "text": "It argues that UBI would eliminate poverty immediately."}, {"id": "C", "text": "It defines UBI, distinguishes related programs, and describes how widely it has been implemented."}, {"id": "D", "text": "It narrates the history of a single pilot project."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Universal basic income", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Universal_basic_income', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-TS001', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to distinctions and then to implementation status.', '{"D": "No individual pilot is described.", "A": "Healthcare is not discussed.", "B": "The text describes the idea and its pilots without claiming an immediate result."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-CE001', 'HDSAT-RW-M24-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Universal basic income (UBI) is a social welfare proposal in which all members of a given population regularly receive a minimum income in the form of an unconditional transfer payment, i.e., without a means test or need to perform work. In contrast, a guaranteed minimum income (GMI) is paid only to those who do not already receive an income that is enough to live on. A UBI would be received independently of any other income. If the level is sufficient to meet a person''s basic needs (i.e., at or above the poverty line), it is considered a full basic income; if it is less than that amount, it is called a partial basic income. As of 2026, no country has implemented a full UBI system, but two countries—Mongolia and Iran—have or had a partial UBI, Mongolia from 2010 to 2012, and Iran still to this day. There have been numerous pilot projects, and the idea is discussed in many countries. Some have labelled UBI as utopian due to its historical origin. There are several welfare arrangements that can be considered similar to basic income, although they are not unconditional. Many countries have a system of child benefit, which is essentially a basic income for guardians of children. A pension may be a basic income for retired persons.', 'Which quotation from the text most directly supports the claim that UBI differs from a guaranteed minimum income?', '[{"id": "A", "text": "Universal basic income is a social welfare proposal in which all members of a given population regularly receive a minimum income."}, {"id": "B", "text": "A UBI would be received independently of any other income."}, {"id": "C", "text": "In contrast, a guaranteed minimum income (GMI) is paid only to those who do not already receive an income that is enough to live on."}, {"id": "D", "text": "As of 2026, no country has implemented a full UBI system."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Universal basic income", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Universal_basic_income', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-CE001', 'C', ARRAY['C']::TEXT[], 'The correct quotation explains the means test that distinguishes GMI from universal payment.', '{"A": "This sentence defines UBI.", "B": "This sentence states UBI''s independence from other income.", "D": "This sentence describes implementation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-CI002', 'HDSAT-RW-M24-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A remittance is a non-commercial transfer of money by a foreign worker, a member of a diaspora community, or a citizen with familial ties abroad, for household income in their home country or homeland. Money sent home by migrants competes with international aid as one of the largest financial inflows to developing countries. Remittance is more than three times as large as the total global foreign aid. In 2021, $780 billion was sent to 800 million people, while foreign aid totalled $200 billion. Most remittance flows from high-income countries to lower-income countries. Workers'' remittances are a significant part of international capital flows, especially with regard to labor-exporting countries. A substantial share of remittance ends up in the hands of banks and money-transfer companies due to fees imposed on money transfers. Governments can play a vital role in enabling migrants to support their families more effectively by implementing measures that help reduce transaction costs. Research suggests that remittances are primarily motivated by altruism, self-interest in exchange, and repayment of past expense. A mix of motivations may coexist, in scientific literature this state of mind is summarized as "tempered altruism and enlightened selfishness". Scholars have linked remittance flows to improved health and education incomes in low-income countries, as the money provides access to food, medicine, health treatments, and education.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Remittances are commercial investments by multinational firms."}, {"id": "B", "text": "Remittances are migrants'' money transfers home, exceed foreign aid in scale, and improve health and education in receiving countries."}, {"id": "C", "text": "Remittances are smaller than total global foreign aid."}, {"id": "D", "text": "Remittances are government grants given to developing countries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Remittance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Remittance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-CI002', 'B', ARRAY['B']::TEXT[], 'The passage defines remittances, describes their scale, and discusses motives and effects.', '{"D": "The text defines remittance as a non-commercial transfer by a foreign worker or diaspora member.", "C": "The text says remittance is more than three times as large as foreign aid.", "A": "The text distinguishes remittances from commercial transfers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-INF002', 'HDSAT-RW-M24-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A remittance is a non-commercial transfer of money by a foreign worker, a member of a diaspora community, or a citizen with familial ties abroad, for household income in their home country or homeland. Money sent home by migrants competes with international aid as one of the largest financial inflows to developing countries. Remittance is more than three times as large as the total global foreign aid. In 2021, $780 billion was sent to 800 million people, while foreign aid totalled $200 billion. Most remittance flows from high-income countries to lower-income countries. Workers'' remittances are a significant part of international capital flows, especially with regard to labor-exporting countries. A substantial share of remittance ends up in the hands of banks and money-transfer companies due to fees imposed on money transfers. Governments can play a vital role in enabling migrants to support their families more effectively by implementing measures that help reduce transaction costs. Research suggests that remittances are primarily motivated by altruism, self-interest in exchange, and repayment of past expense. A mix of motivations may coexist, in scientific literature this state of mind is summarized as "tempered altruism and enlightened selfishness". Scholars have linked remittance flows to improved health and education incomes in low-income countries, as the money provides access to food, medicine, health treatments, and education.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-INF002', 'D', ARRAY['D']::TEXT[], 'A flow several times larger than foreign aid is necessarily a major inflow for recipient countries.', '{"C": "The text calls remittances one of the largest financial inflows to developing countries.", "A": "Their scale relative to aid indicates substantial impact.", "B": "The text does not say remittances replace public services."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-TS002', 'HDSAT-RW-M24-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A remittance is a non-commercial transfer of money by a foreign worker, a member of a diaspora community, or a citizen with familial ties abroad, for household income in their home country or homeland. Money sent home by migrants competes with international aid as one of the largest financial inflows to developing countries. Remittance is more than three times as large as the total global foreign aid. In 2021, $780 billion was sent to 800 million people, while foreign aid totalled $200 billion. Most remittance flows from high-income countries to lower-income countries. Workers'' remittances are a significant part of international capital flows, especially with regard to labor-exporting countries. A substantial share of remittance ends up in the hands of banks and money-transfer companies due to fees imposed on money transfers. Governments can play a vital role in enabling migrants to support their families more effectively by implementing measures that help reduce transaction costs. Research suggests that remittances are primarily motivated by altruism, self-interest in exchange, and repayment of past expense. A mix of motivations may coexist, in scientific literature this state of mind is summarized as "tempered altruism and enlightened selfishness". Scholars have linked remittance flows to improved health and education incomes in low-income countries, as the money provides access to food, medicine, health treatments, and education.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that remittances should be taxed heavily."}, {"id": "B", "text": "It compares remittances with stock market investing."}, {"id": "C", "text": "It defines remittances, compares their scale with aid, and discusses fees, motives, and effects."}, {"id": "D", "text": "It narrates one migrant worker''s journey."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Remittance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Remittance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-TS002', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to scale and then to costs and consequences.', '{"D": "No individual is profiled.", "B": "Stock markets are not discussed.", "A": "Taxation is not recommended."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-CE002', 'HDSAT-RW-M24-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A remittance is a non-commercial transfer of money by a foreign worker, a member of a diaspora community, or a citizen with familial ties abroad, for household income in their home country or homeland. Money sent home by migrants competes with international aid as one of the largest financial inflows to developing countries. Remittance is more than three times as large as the total global foreign aid. In 2021, $780 billion was sent to 800 million people, while foreign aid totalled $200 billion. Most remittance flows from high-income countries to lower-income countries. Workers'' remittances are a significant part of international capital flows, especially with regard to labor-exporting countries. A substantial share of remittance ends up in the hands of banks and money-transfer companies due to fees imposed on money transfers. Governments can play a vital role in enabling migrants to support their families more effectively by implementing measures that help reduce transaction costs. Research suggests that remittances are primarily motivated by altruism, self-interest in exchange, and repayment of past expense. A mix of motivations may coexist, in scientific literature this state of mind is summarized as "tempered altruism and enlightened selfishness". Scholars have linked remittance flows to improved health and education incomes in low-income countries, as the money provides access to food, medicine, health treatments, and education.', 'Which quotation from the text most directly supports the claim that remittances exceed foreign aid?', '[{"id": "A", "text": "Most remittance flows from high-income countries to lower-income countries."}, {"id": "B", "text": "In 2021, $780 billion was sent to 800 million people."}, {"id": "C", "text": "Remittance is more than three times as large as the total global foreign aid."}, {"id": "D", "text": "A remittance is a non-commercial transfer of money by a foreign worker or a member of a diaspora community."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Remittance", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Remittance', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-CE002', 'C', ARRAY['C']::TEXT[], 'The correct quotation directly compares remittances with global foreign aid.', '{"D": "This sentence defines remittance.", "B": "This sentence gives the amount sent.", "A": "This sentence describes the direction of flows."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-CI003', 'HDSAT-RW-M24-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Gentrification is the process whereby the character of a neighborhood changes through the influx of more affluent residents (the "gentry") and investment. There is no agreed-upon definition of gentrification. In public discourse, it has been used to describe a wide array of phenomena, sometimes in a pejorative connotation. Gentrification is a common and controversial topic in urban politics and planning. Gentrification often increases the economic value of a neighborhood, but at the cost of changing demographic composition and potential displacement of incumbent residents. Gentrification is more likely when there is an undersupply of housing and rising housing values in a metropolitan area. The gentrification process is typically the result of increasing attraction to an area by people with higher incomes than those of local residents spilling over from neighboring cities, towns, or neighborhoods. Further steps are increased commercial investments in the area and its infrastructure by real estate developers, local government, or community activists and resulting economic development, increased attraction of business, and lower crime rates. == Origin and etymology == Historians say that gentrification took place in ancient Rome and in Roman Britain, where large villas were replacing small shops by the 3rd century CE. The word gentrification derives from gentry—which comes from Old French genterise, "of gentle birth" (14th century) and "people of gentle birth" (16th century).', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Gentrification changes neighborhoods through affluent newcomers and investment, raising value while potentially displacing residents."}, {"id": "B", "text": "Gentrification has a single agreed definition and no controversy."}, {"id": "C", "text": "Gentrification lowers property values in every case."}, {"id": "D", "text": "Gentrification is the decline of a neighborhood after residents leave."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Gentrification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Gentrification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-CI003', 'A', ARRAY['A']::TEXT[], 'The passage defines gentrification, describes its causes, and weighs its benefits against displacement.', '{"D": "The text describes an influx of more affluent residents and investment.", "B": "The text says there is no agreed-upon definition and that the topic is controversial.", "C": "The text says gentrification often increases economic value."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-INF003', 'HDSAT-RW-M24-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Gentrification is the process whereby the character of a neighborhood changes through the influx of more affluent residents (the "gentry") and investment. There is no agreed-upon definition of gentrification. In public discourse, it has been used to describe a wide array of phenomena, sometimes in a pejorative connotation. Gentrification is a common and controversial topic in urban politics and planning. Gentrification often increases the economic value of a neighborhood, but at the cost of changing demographic composition and potential displacement of incumbent residents. Gentrification is more likely when there is an undersupply of housing and rising housing values in a metropolitan area. The gentrification process is typically the result of increasing attraction to an area by people with higher incomes than those of local residents spilling over from neighboring cities, towns, or neighborhoods. Further steps are increased commercial investments in the area and its infrastructure by real estate developers, local government, or community activists and resulting economic development, increased attraction of business, and lower crime rates. == Origin and etymology == Historians say that gentrification took place in ancient Rome and in Roman Britain, where large villas were replacing small shops by the 3rd century CE. The word gentrification derives from gentry—which comes from Old French genterise, "of gentle birth" (14th century) and "people of gentle birth" (16th century).
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-INF003', 'D', ARRAY['D']::TEXT[], 'The conditions the passage associates with gentrification would be present in a tight market.', '{"C": "The text names undersupply and rising values as conditions that make gentrification more likely.", "A": "Rising values are already part of the stated condition.", "B": "Affluent attraction is described as part of the process."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-TS003', 'HDSAT-RW-M24-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Gentrification is the process whereby the character of a neighborhood changes through the influx of more affluent residents (the "gentry") and investment. There is no agreed-upon definition of gentrification. In public discourse, it has been used to describe a wide array of phenomena, sometimes in a pejorative connotation. Gentrification is a common and controversial topic in urban politics and planning. Gentrification often increases the economic value of a neighborhood, but at the cost of changing demographic composition and potential displacement of incumbent residents. Gentrification is more likely when there is an undersupply of housing and rising housing values in a metropolitan area. The gentrification process is typically the result of increasing attraction to an area by people with higher incomes than those of local residents spilling over from neighboring cities, towns, or neighborhoods. Further steps are increased commercial investments in the area and its infrastructure by real estate developers, local government, or community activists and resulting economic development, increased attraction of business, and lower crime rates. == Origin and etymology == Historians say that gentrification took place in ancient Rome and in Roman Britain, where large villas were replacing small shops by the 3rd century CE. The word gentrification derives from gentry—which comes from Old French genterise, "of gentle birth" (14th century) and "people of gentle birth" (16th century).', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares gentrification with suburbanization."}, {"id": "B", "text": "It profiles a single gentrifying neighborhood."}, {"id": "C", "text": "It argues that gentrification should be banned."}, {"id": "D", "text": "It defines gentrification, describes its causes and effects, and notes its history and etymology."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Gentrification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Gentrification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-TS003', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition to process and then to origins.', '{"B": "No single neighborhood is profiled.", "A": "Suburbanization is not discussed.", "C": "The text describes the debate without recommending a ban."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-CE003', 'HDSAT-RW-M24-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Gentrification is the process whereby the character of a neighborhood changes through the influx of more affluent residents (the "gentry") and investment. There is no agreed-upon definition of gentrification. In public discourse, it has been used to describe a wide array of phenomena, sometimes in a pejorative connotation. Gentrification is a common and controversial topic in urban politics and planning. Gentrification often increases the economic value of a neighborhood, but at the cost of changing demographic composition and potential displacement of incumbent residents. Gentrification is more likely when there is an undersupply of housing and rising housing values in a metropolitan area. The gentrification process is typically the result of increasing attraction to an area by people with higher incomes than those of local residents spilling over from neighboring cities, towns, or neighborhoods. Further steps are increased commercial investments in the area and its infrastructure by real estate developers, local government, or community activists and resulting economic development, increased attraction of business, and lower crime rates. == Origin and etymology == Historians say that gentrification took place in ancient Rome and in Roman Britain, where large villas were replacing small shops by the 3rd century CE. The word gentrification derives from gentry—which comes from Old French genterise, "of gentle birth" (14th century) and "people of gentle birth" (16th century).', 'Which quotation from the text most directly supports the claim that gentrification can displace existing residents?', '[{"id": "A", "text": "There is no agreed-upon definition of gentrification."}, {"id": "B", "text": "Gentrification often increases the economic value of a neighborhood, but at the cost of changing demographic composition and potential displacement of incumbent residents."}, {"id": "C", "text": "Gentrification is a common and controversial topic in urban politics and planning."}, {"id": "D", "text": "Gentrification is the process whereby the character of a neighborhood changes through the influx of more affluent residents and investment."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Gentrification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Gentrification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-CE003', 'B', ARRAY['B']::TEXT[], 'The correct quotation names potential displacement as a cost of rising value.', '{"D": "This sentence defines the process.", "A": "This sentence notes definitional disagreement.", "C": "This sentence describes the topic''s controversy."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-CI004', 'HDSAT-RW-M24-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A food desert is an area that has limited access to affordable, fresh, healthy, and nutritious food. Food deserts are commonly paired with food swamps, which lack grocery stores and instead have convenience stores or fast food. In contrast, an area with greater access to grocers or farmers'' markets with fresh foods may be called a food oasis. Food deserts are commonly associated with food insecurity and are linked to worsening health outcome including an increased risk of developing chronic diseases such as obesity, diabetes, and cardiovascular disease. In 2025, the United States Department of Agriculture reported that an estimated 12.8% of the US population were living in low-income and low-access census tracts. Of this number, 22 million people live in "food deserts", which they define as low-income census tracts that are more than 1 mile (1.6 kilometers) from a supermarket in urban or suburban areas and more than 10 miles (16 kilometers) from a supermarket in rural areas. However, food deserts are not just a complication that arises because of distance to grocery stores; other structural barriers, such as food accessibility, affordability, transportation struggles, and socio-economic constraints, also play a role in food insecurity. Food deserts tend to be inhabited by low-income residents with inadequate access to transportation, which makes them less attractive markets for large supermarket chains.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Food deserts affect only rural residents."}, {"id": "B", "text": "Food deserts are areas with unusually many supermarkets."}, {"id": "C", "text": "Food deserts are low-access areas where distance and other barriers make affordable fresh food hard to obtain and harm health."}, {"id": "D", "text": "Food deserts are defined solely by the price of food."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Food desert", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Food_desert', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-CI004', 'C', ARRAY['C']::TEXT[], 'The passage defines food deserts, describes their health effects, and explains their structural causes.', '{"B": "The text defines food deserts by limited access to affordable, fresh, healthy food.", "A": "The text gives distance thresholds for both urban and rural areas.", "D": "The text says distance alone does not explain them; affordability and transportation also matter."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M24-INF004', 'HDSAT-RW-M24-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A food desert is an area that has limited access to affordable, fresh, healthy, and nutritious food. Food deserts are commonly paired with food swamps, which lack grocery stores and instead have convenience stores or fast food. In contrast, an area with greater access to grocers or farmers'' markets with fresh foods may be called a food oasis. Food deserts are commonly associated with food insecurity and are linked to worsening health outcome including an increased risk of developing chronic diseases such as obesity, diabetes, and cardiovascular disease. In 2025, the United States Department of Agriculture reported that an estimated 12.8% of the US population were living in low-income and low-access census tracts. Of this number, 22 million people live in "food deserts", which they define as low-income census tracts that are more than 1 mile (1.6 kilometers) from a supermarket in urban or suburban areas and more than 10 miles (16 kilometers) from a supermarket in rural areas. However, food deserts are not just a complication that arises because of distance to grocery stores; other structural barriers, such as food accessibility, affordability, transportation struggles, and socio-economic constraints, also play a role in food insecurity. Food deserts tend to be inhabited by low-income residents with inadequate access to transportation, which makes them less attractive markets for large supermarket chains.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M24-INF004', 'B', ARRAY['B']::TEXT[], 'The passage states directly that these conditions make areas less attractive to large supermarket chains.', '{"A": "The text says these conditions make the areas less attractive markets for large chains.", "C": "The text explains the opposite: chains find them less attractive.", "D": "Inadequate transportation raises access problems rather than lowering costs."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
